public record IntVarAlloc(JvmLocal<TInt, IntJitType> local, IntJitType type) : SimpleVarHandler<TInt, IntJitType> {

	/* @Override */
	public Emitter<Ent<N, TInt>> genLoadLegToStack<N>/* where N : Next */(Emitter<N> em,
			JitCodeGenerator<object> gen, MpIntJitType type, int leg, Ext ext) {
